function parseCsv(text){
  var rows=[]; var row=[]; var field=''; var i=0; var inQ=false;
  text=String(text);
  while(i<text.length){
    var c=text[i];
    if(inQ){
      if(c==='"'){ if(text[i+1]==='"'){ field+='"'; i+=2; continue; } inQ=false; i++; continue; }
      field+=c; i++; continue;
    } else {
      if(c==='"'){ inQ=true; i++; continue; }
      if(c===','){ row.push(field); field=''; i++; continue; }
      if(c==='\n'){ row.push(field); rows.push(row); row=[]; field=''; i++; continue; }
      if(c==='\r'){ i++; continue; }
      field+=c; i++; continue;
    }
  }
  row.push(field); rows.push(row);
  if(rows.length && rows[rows.length-1].length===1 && rows[rows.length-1][0]==='' && /\n$/.test(text)) rows.pop();
  return rows;
}
function toCsv(rows){
  return rows.map(function(r){
    return r.map(function(f){
      f=String(f);
      if(/[",\n\r]/.test(f)) return '"'+f.replace(/"/g,'""')+'"';
      return f;
    }).join(',');
  }).join('\n');
}
function toObjects(rows, header){
  if(!rows.length) return [];
  if(header){
    var keys=rows[0]; var out=[];
    for(var r=1;r<rows.length;r++){ var o={}; for(var c=0;c<keys.length;c++) o[keys[c]]=rows[r][c]; out.push(o); }
    return out;
  }
  return rows;
}
function transpose(rows){
  if(!rows.length) return [];
  var cols=rows[0].length; var out=[];
  for(var c=0;c<cols;c++){ var nr=[]; for(var r=0;r<rows.length;r++) nr.push(rows[r][c]); out.push(nr); }
  return out;
}
function summarize(rows, header){
  var cols = rows.length? rows[0].length : 0;
  return { rows: rows.length, cols: cols, headers: (header && rows.length)? rows[0] : [] };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseCsv:parseCsv, toCsv:toCsv, toObjects:toObjects, transpose:transpose, summarize:summarize };
}
if (typeof window !== 'undefined') {
  window.CsvForgePure = { parseCsv:parseCsv, toCsv:toCsv, toObjects:toObjects, transpose:transpose, summarize:summarize };
}
